/g,'<br><br>').replace(/
/g,'<br>');}const riskColors={low:'#16a34a',medium:'#d97706',high:'#dc2626'};const rc=riskColors[p.risk_assessment]||'#6b7280';const reviewItems=(p.review_checklist||[]).map(r=>'<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #f3f4f6;display:flex;gap:6px"><span style="color:#6b7280">□</span>'+esc(r)+'</div>').join('');const labels=(p.suggested_pr_labels||[]).map(l=>'<span style="background:#e5e7eb;color:#374151;font-size:11px;padding:3px 10px;border-radius:12px;margin-right:4px">'+esc(l)+'</span>').join('');const html='<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:sans-serif;color:#111"><div style="max-width:760px;margin:0 auto"><div style="background:#1e293b;color:#fff;padding:18px 26px;border-radius:10px 10px 0 0"><div style="display:flex;gap:8px;align-items:center;margin-bottom:4px">'+(m.breakingChange?'<span style="background:#dc2626;color:#fff;font-size:11px;font-weight:700;padding:2px 8px;border-radius:6px">BREAKING</span>':'')+'<span style="background:#374151;color:#9ca3af;font-size:11px;padding:2px 8px;border-radius:6px">'+esc(m.prType)+'</span></div><div style="font-size:17px;font-weight:700;line-height:1.4">'+esc(m.prTitle)+'</div></div><div style="background:#fff;padding:20px 26px;border:1px solid #e5e7eb;border-top:none;font-size:14px;line-height:1.75">'+mdToHtml(p.markdown_description)+'</div>'+(reviewItems?'<div style="background:#fff;padding:14px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:7px">Review checklist</div>'+reviewItems+'</div>':'')+'<div style="background:#fff;padding:12px 26px;border:1px solid #e5e7eb;display:flex;justify-content:space-between;align-items:center"><div>'+(labels||'')+'</div><div style="display:flex;align-items:center;gap:8px"><span style="font-size:12px;color:#9ca3af">Risk:</span><span style="background:'+rc+'22;color:'+rc+';font-size:12px;font-weight:700;padding:3px 10px;border-radius:8px">'+esc(p.risk_assessment)+'</span><span style="font-size:12px;color:#6b7280">'+esc(p.risk_notes)+'</span></div></div><div style="background:#1e293b;color:#475569;font-size:11px;padding:10px 26px;border-radius:0 0 10px 10px;text-align:center;font-family:monospace">PR Description · '+esc(m.prTitle.slice(0,60))+'</div></div></body></html>';return[{json:{html,replyEmail:m.replyEmail,prTitle:m.prTitle,riskLevel:p.risk_assessment,pr:p}}];
